 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 5 and (nr,nc) not in seen:
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            top = min(rr for rr, _ in cells)
            bottom = max(rr for rr, _ in cells)
            left = min(cc for _, cc in cells)
            right = max(cc for _, cc in cells)
            top_cells = {cc for rr, cc in cells if rr == top}
            gaps = [cc for cc in range(left + 1, right) if cc not in top_cells]
            # A vessel-like outline has one opening in its top edge, two side walls,
            # and a closed bottom. Fill its cavity and extend the indicated ray.
            if len(gaps) != 1 or bottom <= top + 1:
                continue
            opening = gaps[0]
            if not all(grid[rr][left] == 5 and grid[rr][right] == 5 for rr in range(top, bottom + 1)):
                continue
            if not all(grid[bottom][cc] == 5 for cc in range(left, right + 1)):
                continue
            for rr in range(top + 1, bottom):
                for cc in range(left + 1, right):
                    if grid[rr][cc] == 0:
                        out[rr][cc] = 2
            out[top][opening] = 2
            left_lip = sum(1 for cc in range(left, opening) if cc in top_cells)
            right_lip = sum(1 for cc in range(opening + 1, right + 1) if cc in top_cells)
            ray_row = top - 1
            if ray_row >= 0:
                if left_lip > right_lip:
                    for cc in range(0, opening + 1):
                        if out[ray_row][cc] == 0:
                            out[ray_row][cc] = 2
                elif right_lip > left_lip:
                    for cc in range(opening, w):
                        if out[ray_row][cc] == 0:
                            out[ray_row][cc] = 2
    return out
